func decodeString(s string) string {
	type item struct {
		multi int
		res   string
	}
	stack := []item{}
	res, multi := "", 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '[' {
			stack = append(stack, item{multi, res})
			res, multi = "", 0
		} else if c == ']' {
			cur := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			res = cur.res + strings.Repeat(res, cur.multi)
		} else if c >= '0' && c <= '9' {
			multi = multi*10 + int(c-'0')
		} else {
			res += string(c)
		}
	}
	return res
}

func decodeString(s string) string {
	var dfs func(s string, i int) (string, int)
	dfs = func(s string, i int) (string, int) {
		res, multi := "", 0
		for i < len(s) {
			if s[i] >= '0' && s[i] <= '9' {
				multi = multi*10 + int(s[i]-'0')
			} else if s[i] == '[' {
				var tmp string
				tmp, i = dfs(s, i+1)
				res += strings.Repeat(tmp, multi)
				multi = 0
			} else if s[i] == ']' {
				return res, i
			} else {
				res += string(s[i])
			}
			i++
		}
		return res, i
	}
	res, _ := dfs(s, 0)
	return res
}

