class Solution:
    def decodeString(self, s: str) -> str:
        # 初始化栈，存字符串和重复次数
        stack = []
        res = ""
        multi = 0
        for c in s:
            if c == '[':
                stack.append((multi, res))
                res, multi = "", 0
            elif c == ']':
                cur_multi, last_res = stack.pop()
                res = last_res + cur_multi * res
            elif '0' <= c <= '9':
                multi = multi * 10 + int(c)
            else:
                res += c
        return res

class Solution:
    def decodeString(self, s: str) -> str:
        def dfs(s: str, i: int):
            res = ""
            multi = 0
            while i < len(s):
                if '0' <= s[i] <= '9':
                    multi = multi * 10 + int(s[i])
                elif s[i] == '[':
                    tmp, i = dfs(s, i + 1)
                    res += multi * tmp
                    multi = 0
                elif s[i] == ']':
                    return res, i
                else:
                    res += s[i]
                i += 1
            return res, i

        res, _ = dfs(s, 0)
        return res
